public class CacheHitRate {

    public static void main(String[] args) {
        SparkSession spark = SparkSession.builder().appName("CacheHitRate").master("local[*]").getOrCreate();
        JavaRDD<String> onsiteAttributedData = spark.sparkContext.parallelize(Arrays.asList(
                "query1,1678886400",
                "query2,1678886401",
