        List<String> topFrequentQueries = Arrays.asList("query1", "query2");
        Set<String> topFrequentQueriesSet = new HashSet<>(topFrequentQueries);

        // Simulate cache
        Set<String> cache = new HashSet<>();

        // Calculate cache hit/miss for each query
        JavaRDD<Tuple2<String, Integer>> hitMissData = onsiteAttributedData.map(new Function<String, Tuple2<String, Integer>>() {
            @Override
            public Tuple2<String, Integer> call(String line) {
                String[] parts = line.split(",");
                String query = parts[0];
                long timestamp = Long.parseLong(parts[1]);

                int hitOrMiss;
                if (topFrequentQueriesSet.contains(query)) {
                    if (cache.contains(query)) {
                        hitOrMiss = 1; // Cache hit
                    } else {
                        cache.add(query);
                        hitOrMiss = 0; // Cache miss
                    }
                } else {
                    hitOrMiss = -1; // Not a top frequent query, ignore
                }

                return new Tuple2<>(query, hitOrMiss);
            }
        });

        // Calculate hit rate
        long totalQueries = hitMissData.filter(new Function<Tuple2<String, Integer>, Boolean>() {
            @Override
            public Boolean call(Tuple2<String, Integer> tuple) {
                return tuple._2() != -1;
            }
        }).count();

        long hitCount = hitMissData.filter(new Function<Tuple2<String, Integer>, Boolean>() {
            @Override
            public Boolean call(Tuple2<String, Integer> tuple) {
                return tuple._2() == 1;
            }
        }).count();

        double hitRate = (totalQueries > 0) ? (double) hitCount / totalQueries : 0.0;

        System.out.println("Hit Rate: " + hitRate);

        spark.stop();
    }
}
