<script>
  const table = document.querySelector('.table');
  let sortColumn = null;
  let sortOrder = 1; // 1 = ascending, -1 = descending

  table.querySelectorAll('th').forEach(th => {
    th.addEventListener('click', () => {
      const sortType = th.dataset.sort;
      const columnIndex = th.cellIndex;

      if (sortColumn === columnIndex) {
        sortOrder *= -1; // Toggle sort order
      } else {
        sortColumn = columnIndex;
        sortOrder = 1;
      }

      sortTable(sortColumn, sortOrder, sortType);
    });
  });

  function sortTable(column, order, sortType) {
    const rows = Array.from(table.querySelectorAll('tbody tr'));

    rows.sort((a, b) => {
      let cellA = a.cells[column].textContent;
      let cellB = b.cells[column].textContent;

      switch (sortType) {
        case 'number':
          cellA = parseFloat(cellA);
          cellB = parseFloat(cellB);
          break;
        case 'date':
          cellA = new Date(cellA);
          cellB = new Date(cellB);
          break;
      }

      if (cellA < cellB) {
        return -1 * order;
      }
      if (cellA > cellB) {
        return 1 * order;
      }
      return 0;
    });

    // Remove existing rows and append sorted rows
    const tbody = table.querySelector('tbody');
    tbody.innerHTML = '';
    rows.forEach(row => tbody.appendChild(row));
  }
</script>
